const seed=[{id:'orbita',title:'Além da Órbita',category:'Ficção científica',description:'Uma tripulação explora as fronteiras do sistema solar.',cover:'cover-orbita.svg',episodes:[{title:'O chamado',date:'2026-01-01'},{title:'Primeiro contato',date:'2026-01-08'},{title:'O silêncio',date:'2026-12-05'}]},{id:'mares',title:'Marés do Brasil',category:'Documentário',description:'Histórias das comunidades costeiras brasileiras.',cover:'cover-mares.svg',episodes:[{title:'Entre rios e mares',date:'2026-01-01'},{title:'O trabalho das marés',date:'2026-11-25'}]},{id:'lendas',title:'Lendas de Ontem',category:'Suspense',description:'Narrativas e mistérios que atravessam gerações.',cover:'cover-lendas.svg',episodes:[{title:'O antigo casarão',date:'2026-02-01'},{title:'O segredo',date:'2026-11-20'}]}];let series=JSON.parse(localStorage.getItem('cenalivre-demo-series')||'null')||seed;const app=document.getElementById('app');let mode=localStorage.getItem('cenalivre-view')||'grid';let route='home';let active=series[0];let epIdx=0;let q='';const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const available=e=>new Date(e.date+'T00:00:00-03:00').getTime()<=Date.now();const picture=s=>'assets/'+s.cover;const banner=s=>'assets/banner-'+s.id+'.svg';const thumbnail=(s,i)=>'assets/episode-'+String(i%3+1).padStart(2,'0')+'.svg';function persist(){localStorage.setItem('cenalivre-demo-series',JSON.stringify(series))}function nav(){return '<nav><div class="logo">◉ CenaLivre</div><button onclick="go(\'home\')">Início</button><button onclick="go(\'catalog\')">Explorar</button><button onclick="go(\'studio\')">Studio demo</button></nav>'}function go(page,id,index=0){route=page;if(id)active=series.find(s=>s.id===id)||series[0];epIdx=index;render();scrollTo(0,0)}function cards(items){return '<div class="cards '+(mode==='grid'?'grid':'list')+'">'+items.map(s=>'<article class="card" onclick="go(\'series\',\''+s.id+'\')"><img src="'+picture(s)+'" alt="Pôster de '+safe(s.title)+'"><section><h3>'+safe(s.title)+'</h3><div class="tag">'+safe(s.category)+'</div><p class="muted">'+safe(s.description)+'</p></section></article>').join('')+'</div>'}function switcher(){return '<div><button class="'+(mode==='grid'?'active':'')+'" onclick="view(\'grid\')">▦ Grade</button> <button class="'+(mode==='list'?'active':'')+'" onclick="view(\'list\')">☰ Lista</button></div>'}function view(v){mode=v;localStorage.setItem('cenalivre-view',v);render()}function home(){return '<div class="hero" style="background-image:linear-gradient(90deg,#050912aa,#080b10aa),url('+banner(series[0])+')"><div class="inner"><p>ESTREIA EM DESTAQUE</p><h1>'+safe(series[0].title)+'</h1><p>'+safe(series[0].description)+'</p><button class="primary" onclick="go(\'series\',\''+series[0].id+'\')">Ver série</button></div></div><div class="flex"><h2>Descubra nossas histórias</h2>'+switcher()+'</div><section class="block"><h2>Séries em destaque</h2>'+cards(series)+'</section><section class="block"><h2>Documentários</h2>'+cards(series.filter(s=>s.category==='Documentário'))+'</section><section class="block"><h2>Outras produções</h2>'+cards(series.filter(s=>s.category!=='Documentário'))+'</section>'}function catalog(){return '<div class="flex"><h1>Explorar catálogo</h1>'+switcher()+'</div><input placeholder="Buscar séries" value="'+safe(q)+'" oninput="q=this.value;document.getElementById(\'catalog-list\').innerHTML=cards(series.filter(s=>(s.title+s.category).toLowerCase().includes(q.toLowerCase())))"><div id="catalog-list" style="margin-top:20px">'+cards(series.filter(s=>(s.title+s.category).toLowerCase().includes(q.toLowerCase())))+'</div>'}function episodes(){return '<div class="episodes">'+active.episodes.map((e,i)=>'<div class="episode" onclick="'+(available(e)?'go(\'watch\',\''+active.id+'\','+i+')':'void(0)')+'"><img src="'+picture(active)+'" alt=""><div class="grow"><strong>E'+String(i+1).padStart(2,'0')+' — '+safe(e.title)+'</strong><p class="muted">'+(available(e)?'Disponível agora':'Em breve · '+e.date)+'</p></div><button '+(available(e)?'':'disabled')+'>'+(available(e)?'Assistir':'Agendado')+'</button></div>').join('')+'</div>'}function detail(){return '<button onclick="go(\'catalog\')">← Catálogo</button><section class="block flex"><img src="'+picture(active)+'" style="width:min(220px,40%);border-radius:13px"><div style="flex:1;min-width:250px"><p class="tag">'+safe(active.category)+'</p><h1>'+safe(active.title)+'</h1><p>'+safe(active.description)+'</p><p class="muted">Temporada 1 · '+active.episodes.length+' episódios</p></div></section><h2>Temporada 1</h2>'+episodes()}function watch(){const e=active.episodes[epIdx];if(!e||!available(e))return '<h2>Episódio ainda indisponível</h2><button onclick="go(\'series\',\''+active.id+'\')">Voltar</button>';const url=e.youtube?'<iframe class="player" src="https://www.youtube-nocookie.com/embed/'+encodeURIComponent(e.youtube)+'" title="Player" allowfullscreen></iframe>':'<div class="player" style="display:grid;place-items:center"><div style="text-align:center">▶<h2>Player demonstrativo</h2><p class="muted">Configure um ID válido do YouTube no Studio para testar.</p></div></div>';return '<button onclick="go(\'series\',\''+active.id+'\')">← '+safe(active.title)+'</button><h1>E'+(epIdx+1)+' — '+safe(e.title)+'</h1>'+url+'<section class="flex block"><button '+(epIdx===0?'disabled':'')+' onclick="go(\'watch\',\''+active.id+'\','+(epIdx-1)+')">← Anterior</button><button '+(!active.episodes[epIdx+1]||!available(active.episodes[epIdx+1])?'disabled':'')+' onclick="go(\'watch\',\''+active.id+'\','+(epIdx+1)+')">Próximo →</button></section><h2>Episódios</h2>'+episodes()}function studio(){return '<h1>Studio — demonstração</h1><p class="muted">Dados fictícios, sem login real ou API. Alterações gravadas somente neste navegador.</p><div class="studio"><h2>Produções</h2>'+series.map(s=>'<div class="flex" style="padding:10px;border-bottom:1px solid #354050"><strong>'+safe(s.title)+'</strong><button onclick="go(\'edit\',\''+s.id+'\')">Editar</button></div>').join('')+'</div><div class="studio"><h2>Publicação editorial</h2><p>Configure datas por episódio. Episódios futuros podem ser anunciados sem reprodução.</p></div><button onclick="resetDemo()">Restaurar exemplos</button>'}function edit(){return '<button onclick="go(\'studio\')">← Studio</button><h1>Editar — '+safe(active.title)+'</h1><form class="studio" onsubmit="saveEdit(event)"><div class="field"><label>Título</label><input name="title" value="'+safe(active.title)+'" required></div><div class="field"><label>Sinopse</label><input name="description" value="'+safe(active.description)+'"></div><h2>Temporada 1</h2>'+active.episodes.map((e,i)=>'<div class="studio"><b>E'+(i+1)+'</b><div class="field"><label>Nome</label><input name="episodeTitle'+i+'" value="'+safe(e.title)+'"></div><div class="field"><label>Data de estreia</label><input type="date" name="episodeDate'+i+'" value="'+e.date+'"></div><div class="field"><label>ID de vídeo YouTube (opcional)</label><input name="youtube'+i+'" value="'+safe(e.youtube||'')+'"></div></div>').join('')+'<button class="primary" type="submit">Salvar mudanças</button></form>'}function saveEdit(event){event.preventDefault();const f=new FormData(event.target);active.title=f.get('title');active.description=f.get('description');active.episodes.forEach((e,i)=>{e.title=f.get('episodeTitle'+i);e.date=f.get('episodeDate'+i);e.youtube=f.get('youtube'+i)});persist();go('studio')}function resetDemo(){localStorage.removeItem('cenalivre-demo-series');series=structuredClone(seed);render()}function render(){app.innerHTML=nav()+'<main>'+({home, catalog,series:detail,watch,studio,edit}[route]||home)()+'</main>'}render();